-- Apply with a PostgreSQL migration tool before production. SQLAlchemy metadata
-- is only a local-development convenience; do not use create_all as a migration.
CREATE TABLE users (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR NOT NULL, email VARCHAR NOT NULL UNIQUE, password_hash VARCHAR NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, last_login TIMESTAMPTZ);
CREATE TABLE farms (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name VARCHAR NOT NULL, description TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE sessions (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, token VARCHAR NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE fields (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, farm_id INTEGER NOT NULL REFERENCES farms(id) ON DELETE CASCADE, name VARCHAR NOT NULL, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, area_ha DOUBLE PRECISION, soil_texture VARCHAR, organic_matter DOUBLE PRECISION, irrigation_capacity_mm DOUBLE PRECISION, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE field_history (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, field_id INTEGER NOT NULL REFERENCES fields(id) ON DELETE CASCADE, crop VARCHAR, season VARCHAR, year INTEGER, notes TEXT, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE analyses (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, farm_id INTEGER REFERENCES farms(id) ON DELETE SET NULL, field_id INTEGER REFERENCES fields(id) ON DELETE SET NULL, start_date VARCHAR, end_date VARCHAR, priority VARCHAR, season VARCHAR, include_crop_history BOOLEAN NOT NULL DEFAULT FALSE, mode VARCHAR DEFAULT 'offline', status VARCHAR NOT NULL DEFAULT 'pending', summary_json JSONB, created_at TIMESTAMPTZ NOT NULL, started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, error_message TEXT, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX sessions_token_idx ON sessions(token); CREATE INDEX fields_farm_id_idx ON fields(farm_id); CREATE INDEX analyses_user_id_idx ON analyses(user_id);
